class RegimeMosaicSeparableLandscape:
    def __init__(self, dim=5):
        self.dim = dim
        # Generate unique regime parameters for each dimension
        # Basin: Power and scale (Controls curvature near 0)
        self.basin_powers = np.random.uniform(2.0, 6.0, size=dim)
        self.basin_scales = np.random.uniform(0.5, 2.0, size=dim)

        # Phase Transition Boundaries (Random per dimension, ensuring clear separation)
        self.inner_radius = np.random.uniform(0.5, 1.5, size=dim)
        self.left_threshold = np.random.uniform(-5.0, -2.0, size=dim)
        self.right_threshold = np.random.uniform(2.0, 5.0, size=dim)

        # Trap: Oscillatory parameters (Creates local optima in intermediate zone)
        self.trap_freq = np.random.uniform(1.0, 10.0, size=dim)
        self.trap_ampl = np.random.uniform(0.5, 2.0, size=dim)

        # Wall: Penalty type and scale (Creates steep boundaries)
        self.wall_type = np.random.choice([0, 1], size=dim) # 0=Exponential, 1=High-Power
        self.wall_scale = np.random.uniform(0.1, 0.5, size=dim)

    def f(self, x):
        # Ensure x is within bounds [-5, 5]
        x = np.clip(x, -5.0, 5.0)
        total = 0.0

        # Loop through dimensions for perfect separability
        for i in range(self.dim):
            xi = x[i]
            total += self._evaluate_1d(xi, i)

        return total

    def _evaluate_1d(self, xi, i):
        # Determine Regime based on dimension-specific phase transitions

        # Left Wall Regime
        if xi < self.left_threshold[i]:
            return self._compute_wall(xi, self.left_threshold[i], i, side='left')

        # Right Wall Regime
        elif xi > self.right_threshold[i]:
            return self._compute_wall(xi, self.right_threshold[i], i, side='right')

        # Intermediate Trap Regime (Oscillatory)
        elif abs(xi) > self.inner_radius[i]:
            return self._compute_trap(xi, i)

        # Central Basin Regime (Smooth)
        else:
            return self._compute_basin(xi, i)

    def _compute_basin(self, xi, i):
        # Smooth polynomial basin ensuring global minimum at 0
        return self.basin_scales[i] * (abs(xi) ** self.basin_powers[i])

    def _compute_trap(self, xi, i):
        # Oscillatory trap that increases difficulty moving away from basin
        # Adds a trend to ensure it doesn't drop below basin values significantly
        base_trend = self.basin_scales[i] * (self.inner_radius[i] ** self.basin_powers[i])
        return base_trend + self.trap_ampl[i] * np.sin(self.trap_freq[i] * xi)

    def _compute_wall(self, xi, threshold, i, side):
        # Penalty wall that grows steeply away from the threshold
        dist = abs(xi - threshold)

        # Ensure continuity by matching the value of the inner function at the threshold
        inner_val = self._compute_trap(threshold, i) if abs(threshold) > self.inner_radius[i] else self._compute_basin(threshold, i)

        # Apply dimension-specific penalty function
        if self.wall_type[i] == 0:
            # Exponential Penalty
            return inner_val + self.wall_scale[i] * np.exp(dist * 3.0)
        else:
            # High-Power Polynomial Penalty
            return inner_val + self.wall_scale[i] * (dist ** 5.0)

