class RegimeFusionSeparableLandscape:
    """
    An enhanced separable minimization benchmark with extreme non-homogeneity.
    Each dimension uses fundamentally different mathematical regimes,
    creating unique optimization challenges while maintaining perfect separability.
    """

    def __init__(self, dim):
        """Initialize the benchmark function with specified dimensions."""
        self.dim = dim
        # Define different regime types per dimension
        self.dim_regimes = []
        for i in range(dim):
            # Select regime type based on dimension index (varies fundamentally)
            regime_type = i % 5

            # Generate dimension-specific parameters
            if regime_type == 0:
                # Polynomial basin regime
                params = {
                    'type': 'polynomial',
                    'power': 2 + (i % 3),
                    'coeff': 1.0 + 0.5 * (i % 4) / 4.0,
                    'transition': 1.0 + 0.2 * (i % 5)
                }
            elif regime_type == 1:
                # Oscillatory trap regime
                params = {
                    'type': 'oscillatory',
                    'freq': 5.0 + 3.0 * np.sin(i * 0.7),
                    'amp': 2.0 + 1.5 * np.cos(i * 1.3),
                    'phase': i * np.pi / 10.0,
                    'transition': 1.5 + 0.3 * (i % 5)
                }
            elif regime_type == 2:
                # Exponential penalty regime
                params = {
                    'type': 'exponential',
                    'rate': 0.3 + 0.2 * (i % 4),
                    'transition': 2.0 + 0.1 * i,
                    'smooth': True
                }
            elif regime_type == 3:
                # Rational function regime
                params = {
                    'type': 'rational',
                    'shift': 0.5 + 0.25 * (i % 3),
                    'scale': 1.0 + 0.5 * np.sin(i * 0.9),
                    'transition': 1.2 + 0.2 * (i % 5)
                }
            else:  # regime_type == 4
                # Mixed regime (quadratic + sinusoidal)
                params = {
                    'type': 'mixed',
                    'quadratic_weight': 0.6 + 0.2 * (i % 3),
                    'sine_freq': 3.0 + 2.0 * np.sin(i * 0.6),
                    'sine_amp': 1.5 + 1.0 * np.cos(i * 1.1),
                    'transition': 1.8 + 0.15 * (i % 5)
                }

            self.dim_regimes.append(params)

    def _evaluate_polynomial(self, xi, params):
        """Polynomial basin regime evaluation."""
        power = params['power']
        coeff = params['coeff']
        transition = params['transition']

        # Smooth polynomial basin near origin
        if abs(xi) <= transition:
            return coeff * abs(xi) ** power

        # Exponential growth beyond transition
        penalty = coeff * (power * transition ** (power - 1) * (abs(xi) - transition) + transition ** power)
        return penalty

    def _evaluate_oscillatory(self, xi, params):
        """Oscillatory trap regime evaluation."""
        freq = params['freq']
        amp = params['amp']
        phase = params['phase']
        transition = params['transition']

        if abs(xi) <= transition:
            # Quadratic basin with oscillatory modulation
            val = xi ** 2 * (1.0 + 0.5 * np.sin(freq * xi + phase))
            return max(0.0, val)
        else:
            # Steep oscillatory penalty
            return 5.0 * (abs(xi) - transition) ** 2 * (1.0 + 0.3 * np.sin(freq * xi + phase + np.pi/2))

    def _evaluate_exponential(self, xi, params):
        """Exponential penalty regime evaluation."""
        rate = params['rate']
        transition = params['transition']

        if abs(xi) <= transition:
            return xi ** 2
        else:
            return np.exp(rate * (abs(xi) - transition)) * transition ** 2

    def _evaluate_rational(self, xi, params):
        """Rational function regime evaluation."""
        shift = params['shift']
        scale = params['scale']
        transition = params['transition']

        if abs(xi) <= transition:
            # Smooth rational basin
            return scale * xi ** 2 / (1.0 + shift * xi ** 2)
        else:
            # Rational growth beyond transition
            return scale * transition ** 2 / (1.0 + shift * transition ** 2) + 3.0 * (abs(xi) - transition) ** 2

    def _evaluate_mixed(self, xi, params):
        """Mixed regime evaluation (quadratic + sinusoidal)."""
        quad_weight = params['quadratic_weight']
        sine_freq = params['sine_freq']
        sine_amp = params['sine_amp']
        transition = params['transition']

        if abs(xi) <= transition:
            # Weighted combination of quadratic and sinusoidal
            quad = xi ** 2
            sine = sine_amp * np.sin(sine_freq * xi) ** 2
            return quad_weight * quad + (1.0 - quad_weight) * (quad + sine)
        else:
            # Mixed penalty region
            base = xi ** 2
            return base + 2.0 * (abs(xi) - transition) ** 2

    def _evaluate_dimension(self, xi, params):
        """Evaluate a single dimension based on its regime type (completely independent)."""
        regime_type = params['type']

        if regime_type == 'polynomial':
            return self._evaluate_polynomial(xi, params)
        elif regime_type == 'oscillatory':
            return self._evaluate_oscillatory(xi, params)
        elif regime_type == 'exponential':
            return self._evaluate_exponential(xi, params)
        elif regime_type == 'rational':
            return self._evaluate_rational(xi, params)
        elif regime_type == 'mixed':
            return self._evaluate_mixed(xi, params)
        else:
            # Fallback to simple quadratic
            return xi ** 2

    def f(self, x):
        """
        Evaluate the benchmark function at point x.

        Parameters:
        ----------
        x : numpy.ndarray
            Input array of dimension 'dim', values in range [-5.0, 5.0]

        Returns:
        -------
        float
            Function value (to be minimized)
        """
        x = np.asarray(x)
        # Evaluate each dimension completely independently
        total = sum(self._evaluate_dimension(xi, params)
                   for i, (xi, params) in enumerate(zip(x, self.dim_regimes)))
        return float(total)

