                        penalty_thresh, quad_coeff, osc_param, rat_coeff, 
                        exp_rate, trap_depth, step_height, dim_idx):
        # Ensure global minimum at origin with value 0
        if abs(xi) < 1e-10:
            return 0.0

        # Phase 1: Asymmetric quadratic basin (different for pos/neg)
        if xi > 0 and xi <= pos_thresh:
            # Positive side: modulated quadratic
            return quad_coeff * xi ** 2 * (1.0 + 0.5 * np.sin(xi * 5.0))
        elif xi < 0 and xi >= -neg_thresh:
            # Negative side: different modulation
            return quad_coeff * xi ** 2 * (1.0 + 0.4 * np.cos(abs(xi) * 4.0))

        # Phase 2: Step-like transition with dimension-specific height
        elif xi > pos_thresh and xi <= pos_thresh + 0.3:
            return step_height * (1.0 + 0.3 * np.sin(dim_idx * 0.7))
        elif xi < -neg_thresh and xi >= -neg_thresh - 0.2:
            return step_height * (1.0 + 0.3 * np.cos(dim_idx * 0.6))

        # Phase 3: High-frequency oscillatory trap (left of outer)
        elif xi > pos_thresh + 0.3 and xi <= outer_thresh:
            # Right-side oscillatory trap with phase shift
            base = step_height * 0.8
            oscillation = trap_depth * np.sin(osc_param * xi + dim_idx * 0.5) ** 2
            return base + oscillation
        elif xi < -neg_thresh - 0.2 and xi >= -outer_thresh:
            # Left-side oscillatory trap (different frequency and phase)
            base = step_height * 0.8
            oscillation = trap_depth * np.cos(osc_param * abs(xi) + dim_idx * 0.7) ** 2
            return base + oscillation

        # Phase 4: Rational function transition zone
        elif xi > outer_thresh and xi <= penalty_thresh:
            # Right-side rational transition with exponential damping
            return rat_coeff * (xi ** 2 / (1.0 + 0.5 * xi ** 2)) + \
                   trap_depth * 0.3 * np.exp(-xi * 0.1)
        elif xi < -outer_thresh and xi >= -penalty_thresh:
            # Left-side rational transition (different power)
            return rat_coeff * (abs(xi) ** 3 / (1.0 + 0.3 * abs(xi) ** 3)) + \
                   trap_depth * 0.3 * np.exp(-abs(xi) * 0.1)

        # Phase 5: Exponential penalty region (beyond penalty_thresh)
        else:
            # Asymmetric exponential growth
            base_penalty = 10.0
            if xi > 0:
                return base_penalty * np.exp(exp_rate * (xi - penalty_thresh))
            else:
                return base_penalty * np.exp(exp_rate * (abs(xi) - penalty_thresh))

    def get_global_optimum(self):
        """Return the global optimum value"""
        return 0.0

    def get_optimum_location(self):
        """Return the location of global optimum"""
        return np.zeros(self.dim)

import numpy as np

class HeterogeneousRegimeSeparableLandscape:
    """
    A separable minimization benchmark designed to maximize non-homogeneity
    while maintaining strict separability. Each dimension is assigned a unique
    mathematical topology (Regime) with stochastically generated parameters
    (frequencies, scaling, power laws), creating a 'mosaic' of independent
    1D optimization problems. The global minimum is guaranteed at the origin.
    """
    def __init__(self, dim):
        """Initialize the benchmark with specified dimensions."""
        self.dim = dim
        np.random.seed(2023) # Reproducible randomness for benchmark

        # Assign 4 distinct topological structures per dimension
        # 0: Quadratic + Smooth Oscillation
        # 1: Quartic + Rational-like Penalty
        # 2: Absolute-Value + High-Frequency Noise
        # 3: Exponential + Chaotic Transition
        self.topology_map = np.random.randint(0, 4, size=dim)

        # Per-dimension stochastic parameters for phase transitions and scaling
        self.trans_inner = np.random.uniform(0.5, 2.0, size=dim)
        self.trans_outer = np.random.uniform(3.0, 5.0, size=dim)

        self.frequencies = np.random.uniform(2.0, 20.0, size=dim)
        self.scale_factors = np.random.uniform(1.0, 5.0, size=dim)
        self.powers = np.random.choice([1.0, 1.5, 2.0, 3.0, 4.0], size=dim)

    def f(self, x):
        """
        Evaluates the sum of independent dimension costs.

        Parameters:
        ----------
        x : numpy.ndarray
            Input vector of shape (dim,) within [-5.0, 5.0].

        Returns:
        -------
        float
            The total cost (sum of 1D costs).
        """
        x = np.asarray(x)
        total_cost = 0.0

        # Strict Separability: Each dimension is computed independently
        for i in range(self.dim):
            total_cost += self._eval_dim(i, x[i])

        return float(total_cost)

    def _eval_dim(self, i, xi):
        """Evaluate the cost for a single dimension based on its topology."""
        # Bounds Penalty
        if xi < -5.0 or xi > 5.0:
            return 1e12

        topo = self.topology_map[i]

        if topo == 0:
            return self._topo_quad_osc(xi, i)
        elif topo == 1:
            return self._topo_rat_pen(xi, i)
        elif topo == 2:
            return self._topo_abs_noise(xi, i)
        else:
            return self._topo_exp_chaos(xi, i)

    def _topo_quad_osc(self, xi, i):
        # Quadratic Basin (smooth) -> Oscillatory Regime -> Exponential Wall
        # Min at 0
        if abs(xi) < self.trans_inner[i]:
            return xi**2 * self.scale_factors[i]
        elif abs(xi) < self.trans_outer[i]:
            # Oscillations with increasing envelope
            return 0.1 + self.scale_factors[i] * (1.0 + 0.5 * np.sin(self.frequencies[i] * xi))**2
        else:
            return 5.0 + self.scale_factors[i] * np.exp(1.5 * (abs(xi) - self.trans_outer[i]))

    def _topo_rat_pen(self, xi, i):
        # Power Basin -> Rational-like Penalty -> Steep Linear
        # Min at 0
        if abs(xi) < self.trans_inner[i]:
            return abs(xi)**self.powers[i] * self.scale_factors[i]
        elif abs(xi) < self.trans_outer[i]:
            # Simulates a trap without creating new global minima
            # 1/(1 + |xi|^2) decays, so we add growing quadratic
            return self.scale_factors[i] * (xi**2 + 0.5 * np.abs(xi) / (1.0 + abs(xi)))
        else:
            return 5.0 + 10.0 * abs(xi)

    def _topo_abs_noise(self, xi, i):
        # Absolute Basin -> High Freq Noise -> Cubic Wall
        # Min at 0
        if abs(xi) < self.trans_inner[i]:
            return abs(xi) * self.scale_factors[i]
        elif abs(xi) < self.trans_outer[i]:
            # High frequency noise
            return 0.2 + self.scale_factors[i] * abs(np.sin(self.frequencies[i] * xi * 5.0))
        else:
            return 2.0 * abs(xi)**3

    def _topo_exp_chaos(self, xi, i):
        # Smooth Sigmoid Basin -> Chaotic -> Steep Wall
        # Min at 0
        if abs(xi) < self.trans_inner[i]:
            return xi**2 * self.scale_factors[i]
        elif abs(xi) < self.trans_outer[i]:
            # Chaotic looking term that stays positive
            return 1.0 + self.scale_factors[i] * abs(np.sin(self.frequencies[i] * xi + xi**3))
        else:
            return 20.0 * np.exp(2.0 * (abs(xi) - self.trans_outer[i]))

import numpy as np

class RegimeFragmentationSeparableLandscape:
    def __init__(self, dim=5):
        self.dim = dim
        if self.dim < 1:
            self.dim = 1

        # 1. Regime Definitions (Topological Diversity)
        # Inner Basin Types: 0=Quadratic, 1=Quartic, 2=Oscillatory-Weighted, 3=Sharp-Cusp
        self.inner_types = np.random.randint(0, 4, size=self.dim)
        # Outer Wall Types: 0=Exponential, 1=Cubic, 2=Oscillatory-Rise, 3=Quadratic-Linear
        self.outer_types = np.random.randint(0, 4, size=self.dim)

        # 2. Phase Transition Thresholds (Non-Homogeneity Driver)
        # Each dimension switches behavior at a different distance from origin
        self.thresholds = np.random.uniform(1.0, 3.5, size=self.dim)

        # 3. Scaling Parameters (Geometric Diversity)
        self.inner_scale = np.random.uniform(0.5, 2.0, size=self.dim)
        self.outer_scale = np.random.uniform(0.5, 2.5, size=self.dim)

        # 4. Frequency for Oscillatory Components
        self.frequencies = np.random.uniform(5.0, 15.0, size=self.dim)

    def f(self, x):
        # Ensure input is a numpy array
        x = np.asarray(x)
        if x.ndim == 0:
            x = x.reshape(1)

        # Clip to bounds [-5.0, 5.0]
        x = np.clip(x, -5.0, 5.0)

        total_cost = 0.0

        # Strict Separability Loop: Sum of independent 1D evaluations
        for i in range(self.dim):
            val = x[i]
            dist = np.abs(val)
            threshold = self.thresholds[i]

            # --- Evaluate Inner Regime Function ---
            if self.inner_types[i] == 0:
                raw_inner = val ** 2
            elif self.inner_types[i] == 1:
                raw_inner = val ** 4
            elif self.inner_types[i] == 2:
                raw_inner = (1.0 - np.cos(self.frequencies[i] * val)) * (val ** 2)
            else:
                raw_inner = (np.abs(val) ** 1.5)

            f_inner = self.inner_scale[i] * raw_inner

            # --- Evaluate Outer Regime Function ---
            if self.outer_types[i] == 0:
                raw_outer = np.exp(dist)
            elif self.outer_types[i] == 1:
                raw_outer = dist ** 3
            elif self.outer_types[i] == 2:
                raw_outer = (dist + 0.5 * np.sin(self.frequencies[i] * dist))
            else:
                raw_outer = (dist ** 2 + dist)

            f_outer = self.outer_scale[i] * raw_outer

            # --- Calculate Continuity Offset ---
            # Ensures f_inner(threshold) == f_outer(threshold) for continuity,
            # while maintaining a derivative discontinuity (Phase Transition)

            # Inner Value at Threshold
            if self.inner_types[i] == 0:
                val_in = threshold ** 2
            elif self.inner_types[i] == 1:
                val_in = threshold ** 4
            elif self.inner_types[i] == 2:
                val_in = (1.0 - np.cos(self.frequencies[i] * threshold)) * (threshold ** 2)
            else:
                val_in = (threshold ** 1.5)

            val_in *= self.inner_scale[i]

            # Outer Value at Threshold
            if self.outer_types[i] == 0:
                val_out = np.exp(threshold)
            elif self.outer_types[i] == 1:
                val_out = threshold ** 3
            elif self.outer_types[i] == 2:
                val_out = (threshold + 0.5 * np.sin(self.frequencies[i] * threshold))
            else:
                val_out = (threshold ** 2 + threshold)

            val_out *= self.outer_scale[i]

            offset = val_in - val_out

            # --- Regime Selection with Hard Transition ---
            if dist < threshold:
                cost_dim = f_inner
            else:
                cost_dim = f_outer + offset

            # Ensure Non-Negativity (Global Min at 0)
            if cost_dim < 0.0:
                cost_dim = 0.0

            total_cost += cost_dim

        return float(total_cost)

import numpy as np

class DimensionRegimePhaseLandscape:
    """
    A strictly separable minimization benchmark with dimension-specific
    mathematical regime mosaics and phase transitions.
    Creates extreme non-homogeneity through independent 1D landscapes
    with unique mathematical families per dimension.
    """

    def __init__(self, dim):
        """Initialize the benchmark function with specified dimensions."""
        self.dim = dim

        # Random seed for reproducibility
        np.random.seed(42 + dim)

        # Dimension-specific mathematical family (0-4)
        self.math_families = np.random.randint(0, 5, size=dim)

        # Dimension-specific regime boundaries
        self.regime_boundaries = np.random.uniform(0.5, 3.5, size=dim)

        # Dimension-specific scaling factors
        self.scale_factors = np.random.uniform(0.3, 2.0, size=dim)

        # Dimension-specific phase shift parameters
        self.phase_shifts = np.random.uniform(-np.pi, np.pi, size=dim)

        # Dimension-specific amplitude modifiers
        self.amplitude_mods = np.random.uniform(1.0, 4.0, size=dim)

        # Dimension-specific regime complexity (number of sub-regimes)
        self.regime_complexity = np.random.randint(2, 5, size=dim)

    def _polynomial_regime(self, x, dim_idx):
        """Polynomial mathematical regime with dimension-specific coefficients."""
        p1 = 0.5 + 0.3 * (dim_idx % 3)
        p2 = 1.0 + 0.2 * np.sin(dim_idx * 0.7)
        p3 = 2.0 + 0.4 * np.cos(dim_idx * 1.1)
        return p1 * x**2 + p2 * np.abs(x)**3 + p3 * x**4

    def _trigonometric_regime(self, x, dim_idx):
        """Trigonometric regime with phase transitions."""
        freq = 1.0 + 2.0 * np.sin(dim_idx * 0.8)
        phase = self.phase_shifts[dim_idx]
        amp = self.amplitude_mods[dim_idx]
        return amp * (1 - np.cos(freq * x + phase)) + 0.1 * x**2

    def _exponential_regime(self, x, dim_idx):
        """Exponential regime with asymmetric walls."""
        rate = 0.5 + 1.5 * np.sin(dim_idx * 0.6)
        return rate * np.exp(0.5 * x**2) - rate + 0.1 * x**2

    def _rational_regime(self, x, dim_idx):
        """Rational regime with poles and asymptotes."""
        pole_offset = 1.2 + 0.8 * np.sin(dim_idx * 0.9)
        denom = (x - pole_offset)**2 + 0.1
        return self.amplitude_mods[dim_idx] / denom + 0.05 * x**2

    def _piecewise_regime(self, x, dim_idx):
        """Piecewise regime with multiple sub-regimes."""
        val = 0.0
        complexity = self.regime_complexity[dim_idx]
        for i in range(complexity):
            threshold = (i + 1) / complexity * self.regime_boundaries[dim_idx]
            if abs(x) < threshold:
                val = (2.0 - i * 0.3) * (x**2 + 0.1)
        # Final regime for larger values
        val += self.scale_factors[dim_idx] * np.abs(x)**(1.5 + (dim_idx % 3) * 0.5)
        return val

    def _select_regime_function(self, x, dim_idx):
        """Select the appropriate mathematical regime based on dimension."""
        family = self.math_families[dim_idx]

        if family == 0:
            return self._polynomial_regime(x, dim_idx)
        elif family == 1:
            return self._trigonometric_regime(x, dim_idx)
        elif family == 2:
            return self._exponential_regime(x, dim_idx)
        elif family == 3:
            return self._rational_regime(x, dim_idx)
        elif family == 4:
            return self._piecewise_regime(x, dim_idx)
        else:
            return self._polynomial_regime(x, dim_idx)

    def _regime_switch(self, x, dim_idx):
        """Apply regime switch based on phase boundaries."""
        base_val = self._select_regime_function(x, dim_idx)
        boundary = self.regime_boundaries[dim_idx]

        # Inner regime (smooth basin)
        if abs(x) < boundary * 0.5:
            return base_val * self.scale_factors[dim_idx]

        # Transition regime with added complexity
        elif abs(x) < boundary:
            return base_val + 1.5 * np.abs(np.sin(x * (1 + dim_idx * 0.3)))

        # Outer regime with barriers
        elif abs(x) < boundary * 2.0:
            return base_val + 2.0 * np.exp(0.3 * (abs(x) - boundary))

        # Boundary penalty regime
        else:
            return base_val + 5.0 * np.exp(0.5 * (abs(x) - boundary * 2.0))

    def f(self, x):
        """
        Evaluate the benchmark function at point x.

        Parameters:
        ----------
        x : numpy.ndarray
            Input array of dimension 'dim', values in range [-5.0, 5.0]

        Returns:
        -------
        float
            Function value (to be minimized)
        """
        x = np.asarray(x)
        total = 0.0

        for i, xi in enumerate(x):
            # Strictly separable: each dimension is independent
            val = self._regime_switch(xi, i)
            total += val

        return float(total)
